style.css:
img {
  filter:
    brightness(1.2)
    contrast(1.15)
    drop-shadow(0 0 8px rgba(255,255,255,0.9))
    drop-shadow(0 0 20px rgba(255,255,255,0.8))
    drop-shadow(0 0 40px rgba(255,255,255,0.7))
    drop-shadow(0 0 80px rgba(255,255,255,0.5));

  animation: glow 3s ease-in-out infinite alternate;
}

@keyframes glow {
  from {
    filter:
      brightness(1.1)
      drop-shadow(0 0 8px rgba(255,255,255,0.8))
      drop-shadow(0 0 20px rgba(255,255,255,0.6));
  }
  to {
    filter:
      brightness(1.3)
      drop-shadow(0 0 15px rgba(255,255,255,1))
      drop-shadow(0 0 35px rgba(255,255,255,0.9))
      drop-shadow(0 0 70px rgba(255,255,255,0.7));
  }
}
